sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?place ?country WHERE {
  VALUES ?place { dbr:Chyoryumche dbr:Rodnikovka,_Republic_of_Bashkortostan }
  OPTIONAL { ?place dbp:country ?dbpCountry . }
  OPTIONAL { ?place dbo:country ?dboCountry . }
  BIND(COALESCE(?dbpCountry, ?dboCountry) AS ?country)
}
LIMIT 100

